float vrchHandFocusSample(vec2 uv) {
  vec4 value = vrchSampleSignalTexture(0, clamp(uv, vec2(0.0), vec2(1.0)));
  return max(max(value.r, value.g), max(value.b * uParam_trail, value.a));
}
float vrchHandFocusMask(vec2 uv, float radius) {
  float aspect = iResolution.x / max(iResolution.y, 1.0);
  vec2 x = vec2(radius / max(aspect, 0.01), 0.0);
  vec2 y = vec2(0.0, radius);
  float value = vrchHandFocusSample(uv);
  value = max(value, vrchHandFocusSample(uv + x));
  value = max(value, vrchHandFocusSample(uv - x));
  value = max(value, vrchHandFocusSample(uv + y));
  value = max(value, vrchHandFocusSample(uv - y));
  value = max(value, vrchHandFocusSample(uv + x + y));
  value = max(value, vrchHandFocusSample(uv + x - y));
  value = max(value, vrchHandFocusSample(uv - x + y));
  value = max(value, vrchHandFocusSample(uv - x - y));
  return value;
}
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / max(iResolution.xy, vec2(1.0));
  vec4 source = vrchSampleSource0(uv);
  float confidence = vrchReadSignal(0);
  float motion = vrchReadSignal(1);
  vec4 tracking = vrchSampleSignalTexture(0, uv);
  float spread = vrchHandFocusMask(uv, uParam_hand_area * (1.0 + motion * 0.2));
  float edge0 = mix(0.02, 0.5, clamp(uParam_softness, 0.0, 1.0));
  float handMask = smoothstep(edge0, 0.92, spread) * confidence;
  vec2 px = vec2(uParam_blur) / max(iResolution.xy, vec2(1.0));
  vec3 blurred = source.rgb;
  blurred += vrchSampleSource0(uv + vec2(px.x, 0.0)).rgb;
  blurred += vrchSampleSource0(uv - vec2(px.x, 0.0)).rgb;
  blurred += vrchSampleSource0(uv + vec2(0.0, px.y)).rgb;
  blurred += vrchSampleSource0(uv - vec2(0.0, px.y)).rgb;
  blurred += vrchSampleSource0(uv + px).rgb;
  blurred += vrchSampleSource0(uv - px).rgb;
  blurred += vrchSampleSource0(uv + vec2(px.x, -px.y)).rgb;
  blurred += vrchSampleSource0(uv + vec2(-px.x, px.y)).rgb;
  blurred *= 0.111111;
  float luma = dot(blurred, vec3(0.2126, 0.7152, 0.0722));
  vec3 treated = mix(blurred, vec3(luma), uParam_desaturate) * (1.0 - uParam_dim);
  float effectAmount = clamp(uParam_amount * confidence * (1.0 - handMask), 0.0, 1.0);
  vec3 color = mix(source.rgb, treated, effectAmount);
  float outline = tracking.a * uParam_outline * confidence;
  color += uParam_outline_color.rgb * outline * 0.35;
  fragColor = vec4(color, source.a);
}
